def _rapport_html(which=None):
    """Page HTML des rapports quotidiens (accessible via favori : /rapport).
    Liste les rapports disponibles et affiche le plus récent, sans ouvrir de fichier."""
    import glob, html as _h
    files = sorted(glob.glob(os.path.join(RAPPORT_DIR, "rapport_*.txt")), reverse=True)
    if which:                                     # sélection dans la liste déroulante
        safe = os.path.basename(which)            # jamais de chemin fourni par l'URL
        cand = os.path.join(RAPPORT_DIR, safe)
        if cand in files:
            files = [cand] + [f for f in files if f != cand]
    if not files:
        body = ("<p class='vide'>Aucun rapport pour l'instant.<br>Lance <code>py daily.py</code> "
                "(ou attends la t\u00e2che quotidienne) pour en g\u00e9n\u00e9rer un.</p>")
        opts = ""
    else:
        with open(files[0], encoding="utf-8") as f:
            body = "<pre id='txt'>" + _h.escape(f.read()) + "</pre>"
        opts = "".join(
            f"<option value='{os.path.basename(p)}'>{os.path.basename(p)[8:-4]}</option>"
            for p in files[:60])
    return """<!doctype html><html lang="fr"><head><meta charset="utf-8">
<title>Rapports \u2014 Flow Engine</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
 body{background:#0b0d12;color:#e8e6e3;font-family:ui-monospace,Menlo,Consolas,monospace;margin:0;padding:22px;}
 .bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:16px;}
 h1{font-size:16px;margin:0;letter-spacing:.5px;}
 a,select,button{background:#12151d;color:#e8e6e3;border:1px solid #262b36;border-radius:7px;
   padding:6px 11px;font-family:inherit;font-size:12px;text-decoration:none;cursor:pointer;}
 a:hover,button:hover{border-color:#3a3f4b;}
 pre{background:#101319;border:1px solid #1e222c;border-radius:10px;padding:18px;
   white-space:pre-wrap;line-height:1.55;font-size:12.5px;max-width:1000px;}
 .vide{color:#8b949e;}
 code{background:#1a1e27;padding:2px 6px;border-radius:4px;}
</style></head><body>
<div class="bar">
  <h1>\U0001F4C8 RAPPORTS QUOTIDIENS</h1>
  <a href="/">\u2190 Dashboard</a>
  """ + (f"<select onchange=\"location='/rapport?f='+this.value\">{opts}</select>" if opts else "") + """
  <button onclick="navigator.clipboard.writeText(document.getElementById('txt').innerText).then(()=>{this.textContent='\u2713 Copi\u00e9 !';setTimeout(()=>this.textContent='\U0001F4CB Copier pour Claude',1500);})">\U0001F4CB Copier pour Claude</button>
</div>
""" + body + """
</body></html>"""


def _backtest_html(asset="BTC"):
    """Page /backtest : lance le backtest sur l'actif demande et rend le resultat."""
    import io, contextlib, html as _h
    buf = io.StringIO()
    try:
        import importlib, backtest as bt
        importlib.reload(bt)
        old = sys.argv
        sys.argv = ["backtest.py", asset, "mensuel"]
        try:
            with contextlib.redirect_stdout(buf):
                bt.main()
        finally:
            sys.argv = old
        txt = buf.getvalue()
    except Exception as e:
        txt = (f"Backtest indisponible : {e}\n\n"
               "Verifie que backtest.py est bien dans le meme dossier.")
    try:
        ids = sorted(fe.ASSETS.keys())
    except Exception:
        ids = ["BTC", "ETH"]
