class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):  # silence les logs HTTP
        pass

    def _send(self, code, body, ctype):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        # Outil local mono-utilisateur : jamais d'interet a ce que le navigateur mette en
        # cache une reponse perimee. Evite le piege "j'ai relance le serveur mais je vois
        # toujours l'ancienne page" apres une mise a jour du code.
        self.send_header("Cache-Control", "no-store, must-revalidate")
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        path = self.path.split("?")[0]
        if path == "/" or path == "/index.html":
            if os.path.exists("dashboard.html"):
                with open("dashboard.html", "rb") as f:
                    self._send(200, f.read(), "text/html; charset=utf-8")
            else:
                self._send(200, base64.b64decode(HTML_B64), "text/html; charset=utf-8")
            return
        if path == "/manifest.json":
            man = json.dumps({
                "name": "Flow Engine", "short_name": "Flow Engine",
                "start_url": "/", "scope": "/", "display": "standalone",
                "background_color": "#0b0d12", "theme_color": "#0b0d12",
                "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png",
                           "purpose": "any"},
                          {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png",
                           "purpose": "any"}]})
            self._send(200, man.encode(), "application/manifest+json")
            return
        if path in ("/icon-192.png", "/icon-512.png"):
            self._send(200, base64.b64decode(_ICON_192 if "192" in path else _ICON_512),
                       "image/png")
            return
        if path == "/chart":
            self._send(200, _chart_html().encode("utf-8"), "text/html; charset=utf-8")
            return
        if path == "/chartjs.js":
            self._send(200, _chartjs_source().encode("utf-8"),
                       "application/javascript; charset=utf-8")
            return
        if path.startswith("/api/niveaux/"):
            a = path.split("/api/niveaux/", 1)[1].split("?")[0]
            import urllib.parse as _up
            a = _up.unquote(a).upper()
            try:
                rows = fe._read_history_file(a, "mensuel")
                out = [{"date": r["date"], "max_pain": r.get("max_pain"),
                        "flip": r.get("flip"), "call_wall": r.get("call_wall"),
                        "put_wall": r.get("put_wall")} for r in rows]
                self._send(200, json.dumps(out).encode(), "application/json")
            except Exception as e:
                self._send(500, json.dumps({"error": str(e)}).encode(), "application/json")
            return
        if path.startswith("/api/candles/"):
            qs = self.path.split("?", 1)[1] if "?" in self.path else ""
            res = "1h"
            for kv in qs.split("&"):
                if kv.startswith("res="):
                    res = kv[4:]
            a = path.split("/api/candles/", 1)[1].split("?")[0]
            import urllib.parse as _up
            a = _up.unquote(a).upper()
            try:
                data = fe.price_candles(a, res)
                self._send(200, json.dumps(data or {}).encode(), "application/json")
            except Exception as e:
                self._send(500, json.dumps({"error": str(e)}).encode(), "application/json")
            return
        if path == "/backtest":
            qs = self.path.split("?", 1)[1] if "?" in self.path else ""
            a = "BTC"
            for kv in qs.split("&"):
                if kv.startswith("a="):
                    a = kv[2:].upper()[:12]
            self._send(200, _backtest_html(a).encode("utf-8"), "text/html; charset=utf-8")
            return
        if path == "/rapport" or path == "/rapports":
            qs = self.path.split("?", 1)[1] if "?" in self.path else ""
            sel = None
            for kv in qs.split("&"):
                if kv.startswith("f="):
                    sel = kv[2:]
            self._send(200, _rapport_html(sel).encode("utf-8"),
                       "text/html; charset=utf-8")
            return
        if path == "/api/assets":
            body = json.dumps([{"id": k, "label": v["label"],
                                "cat": v.get("cat", "macro"), "group": v.get("group", ""),
                                "ticker": (v["cboe"].lstrip("_") if v.get("source") == "cboe" and v.get("cboe") else k)}
                               for k, v in fe.ASSETS.items()])
            self._send(200, body.encode(), "application/json")
            return
        if path.startswith("/api/"):
            import urllib.parse
            asset = urllib.parse.unquote(path.split("/api/")[1]).upper()
            qs = urllib.parse.parse_qs(self.path.split("?")[1]) if "?" in self.path else {}
            dte = qs.get("dte", [None])[0]
            fresh = qs.get("fresh", [None])[0]
            sign = qs.get("sign", [None])[0]              # "fixed" | "adaptive" | None(=réglage global)
            if sign not in ("fixed", "adaptive"):
                sign = None
            ck = f"{asset}:{dte}:{sign}"                  # le mode fait partie de la clé de cache
            now = time.time()
            if not fresh and ck in _CACHE and now - _CACHE[ck][0] < _TTL:
                self._send(200, _CACHE[ck][1], "application/json")
                return
            try:
                data = fe.analyse(asset, dte_days=dte, sign_mode=sign)
                body = json.dumps(data, default=str).encode()
                _CACHE[ck] = (now, body)
                self._send(200, body, "application/json")
            except Exception as e:
                traceback.print_exc()
                self._send(500, json.dumps({"error": str(e)}).encode(), "application/json")
            return
        self._send(404, b"not found", "text/plain")


def local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "127.0.0.1"


